<?php
require_once __DIR__ . '/helpers.php';
$user=require_role('admin');$pdo=db();$method=$_SERVER['REQUEST_METHOD'];
if($method==='GET'){$tax=$pdo->query("SELECT id,nombre,porcentaje,estado,actualizado_en FROM impuestos WHERE nombre='IVA' ORDER BY id LIMIT 1")->fetch();$cfg=$pdo->query('SELECT saldo_minimo_alerta FROM tienda_configuracion WHERE id=1')->fetch();json_response(['ok'=>true,'impuesto'=>$tax,'saldo_minimo_alerta'=>(float)($cfg['saldo_minimo_alerta']??100)]);}
if($method==='PUT'){require_csrf();$d=body_json();$tax=filter_var($d['iva_porcentaje']??null,FILTER_VALIDATE_FLOAT);$low=filter_var($d['saldo_minimo_alerta']??null,FILTER_VALIDATE_FLOAT);if($tax===false||$tax<0||$tax>30)json_response(['error'=>'El IVA debe estar entre 0 y 30 %.'],422);if($low===false||$low<0||$low>100000)json_response(['error'=>'El umbral de saldo bajo no es válido.'],422);$pdo->beginTransaction();try{$pdo->prepare("UPDATE impuestos SET porcentaje=?,estado='activo',actualizado_por=? WHERE nombre='IVA'")->execute([$tax,$user['id']]);$pdo->prepare('UPDATE tienda_configuracion SET saldo_minimo_alerta=?,actualizado_por=? WHERE id=1')->execute([$low,$user['id']]);$pdo->commit();json_response(['ok'=>true,'mensaje'=>'Configuración comercial actualizada.']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(['error'=>'No fue posible guardar la configuración.'],500);}}
json_response(['error'=>'Método no permitido.'],405);
